}

let pageImageUrls=[];
if(requiredKeys.length>0){
  for(const key of requiredKeys){
    const keyR2=key==='p00'?(pagesR2.p00?'p00':(pagesR2.p00_dedication?'p00_dedication':'p00')):key;
