}

const bust=encodeURIComponent(String(manifest.runStamp||manifest.generatedAt||orderId||Date.now()));
pageImageUrls=pageImageUrls.map(u=>u+(u.includes('?')?'&':'?')+'v='+bust);

const expectedPageCount=pageImageUrls.length||17;
