const coverPdfR2Key=manifest.coverPdfR2Key||manifest.pdfGeneration?.coverPdf||root.coverPdfR2Key||`book-mvp-simple-adventure/orders/${orderId}/cover_${orderId}.pdf`;
let shippingAddress=manifest.shippingAddress||manifest.shipping_address||root.shipping_address||root.shippingAddress||{};

if(!shippingAddress?.phone_number&&!shippingAddress?.phone){
  try{
    const m1Ref=firstNonEmpty(root.one_manifest_url,`book-mvp-simple-adventure/orders/${orderId}/manifests/1-manifest.json`);
    const m1Url=isUrl(m1Ref)?String(m1Ref):`${backendUrl}/api/manifests/${m1Ref}`;
    const m1=await http({method:'GET',url:m1Url,json:true,ignoreHttpStatusErrors:true});
    if(m1&&typeof m1==='object'&&!m1.error){
      const sa=m1.order?.orderDetails?.shippingAddress||m1.shippingAddress||{};
      if(sa.phone||sa.phone_number||sa.phoneNumber){
        shippingAddress={...shippingAddress,name:shippingAddress.name||sa.name,street1:shippingAddress.street1||sa.address||sa.street1,city:shippingAddress.city||sa.city,state_code:shippingAddress.state_code||(sa.state||'').toUpperCase(),postcode:shippingAddress.postcode||sa.zip||sa.postcode,country_code:shippingAddress.country_code||(sa.country||sa.country_code||'US').toUpperCase(),phone_number:sa.phone||sa.phone_number||sa.phoneNumber,email:shippingAddress.email||sa.email};
      }
    }
  }catch(e){}
}

const childName=(root.character_specs?.childName||manifest.character_specs?.childName||'Book').toString().trim()||'Book';
return { json:{...root,...manifest,CONFIG,orderId,pageImageUrls,expectedPageCount,pdfFilename,pdfR2Key,coverPdfR2Key,shippingAddress,childName} };

// Config + Validate Sibling Group — add CONFIG, validate, emit N items (one per sibling)
