  throw new Error(`[QA Check Cover PDF] Client error (status=${statusCode}, orderId=${orderId}, reason=${payload.reasonCode || payload.error || 'unknown'}, body=${bodyPreview || 'n/a'})`);
}

const qaCover = { statusCode, passed: Boolean(payload.passed), skipped: false, reasonCode: payload.reasonCode || 'unknown', reason: payload.reason || 'unknown', failedPages: Array.isArray(payload.failedPages) ? payload.failedPages : [], warnings: Array.isArray(payload.warnings) ? payload.warnings : [], raw: payload };

// Gate: combine interior + cover results.
const qaInterior = item.qaInterior || {};
const intPassed = Boolean(qaInterior.passed);
const covPassed = Boolean(qaCover.passed);

if (!intPassed && typeof qaInterior.passed === 'boolean') {
  throw new Error(`[W4.1 QA] Interior failed for ${orderId} (${qaInterior.reasonCode || 'failed'})`);
}
if (!covPassed) {
  throw new Error(`[W4.1 QA] Cover failed for ${orderId} (${qaCover.reasonCode || 'failed'})`);
}

return { json: { ...item, qaCover, qaPassed: true, qaSkipped: false, qaFailedPages: [...(qaInterior.failedPages || []), ...(qaCover.failedPages || [])] } };

// Reattach context after interior file download to preserve json + binary for R2 upload.
const item = $input.item;
const out = item?.json || {};
function latest(node){ try { return ($items(node, 0, $runIndex)?.[0]?.json) || null; } catch { return null; } }
const ctx = latest('Poll PDFMonkey until ready') || latest('Validate & Normalize Per Sibling') || {};
return { json: { ...ctx, ...out }, binary: item?.binary };

// Reattach canonical context after cover upload/PATCH side-effects before QA.
const out = $input.item.json || {};
function latest(node){ try { return ($items(node, 0, $runIndex)?.[0]?.json) || null; } catch { return null; } }
const ctx = latest('Poll Cover PDFMonkey until ready') || latest('Reattach Cover Context (PDFM)') || latest('Validate & Normalize Per Sibling') || {};
return { json: { ...ctx, ...out } };

// Guard required fields before QA nodes.
const j = $input.item.json || {};
const missing = [];
if (!(j.orderId || j.amazonOrderId || j.amazon_order_id)) missing.push('orderId');
if (!(j.pdfR2Key || j.interiorPdfR2Key)) missing.push('pdfR2Key');
if (!j.coverPdfR2Key) missing.push('coverPdfR2Key');
if (!j.CONFIG?.backendApiToken) missing.push('CONFIG.backendApiToken');

// Validate derived QA endpoint format early for clearer diagnostics.
const assetBase = String(j.CONFIG?.defaults?.trimIn?.assetBase || 'https://admin.littleherolabs.com/api/assets/');
const backendUrl = assetBase.replace(/\/api\/assets\/?$/, '');
const qaCheckUrl = `${backendUrl}/api/render/qa-check-pdf`;
if (!/^https?:\/\/[^\s]+$/i.test(qaCheckUrl)) missing.push('qaCheckUrl');

if (missing.length) {
  throw new Error(`[Guard QA Inputs] Missing ${missing.join(', ')} (hasOrderId=${!!(j.orderId||j.amazonOrderId||j.amazon_order_id)}, hasConfig=${!!j.CONFIG}, hasPdfR2Key=${!!(j.pdfR2Key||j.interiorPdfR2Key)}, hasCoverPdfR2Key=${!!j.coverPdfR2Key}, qaCheckUrl=${qaCheckUrl || 'n/a'}, sourceNode=Reattach QA Context)`);
}
return { json: j };
